INSERT INTO `international_universities` (`id`, `country`, `country_th`, `name_en`, `city`, `qs_rank`, `qs_rank_display`, `website_url`, `admission_note`, `documents_required`, `test_policy`, `deadlines`, `application_fee`, `criteria_source_url`, `criteria_verified_at`, `sort_order`, `created_at`) VALUES (61,'United States','สหรัฐอเมริกา','Massachusetts Institute of Technology (MIT)','Cambridge',1,'1','https://web.mit.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','แบบฟอร์มสมัคร MIT First-Year Application | รายงานจากโรงเรียน (Secondary School Report) พร้อม transcript | จดหมายแนะนำจากครู 2 ฉบับ (แนะนำ 1 ฉบับจากครูคณิตศาสตร์/วิทยาศาสตร์ และอีก 1 ฉบับจากครูมนุษยศาสตร์/สังคมศาสตร์/ภาษา) | คะแนนสอบ SAT หรือ ACT | ค่าธรรมเนียมสมัคร $75 (หรือขอยกเว้นได้) | Portfolio ผลงานสร้างสรรค์ (ไม่บังคับ)','บังคับใช้คะแนน SAT หรือ ACT (ไม่รับ SAT Essay หรือ ACT Writing) ไม่มีคะแนนขั้นต่ำตายตัวเพราะพิจารณาตามบริบทของผู้สมัครแต่ละคน คะแนนภาษาอังกฤษแนะนำอย่างยิ่งสำหรับผู้ที่ใช้ภาษาอังกฤษน้อยกว่า 5 ปีหรือไม่ได้ใช้ที่บ้าน/โรงเรียน คะแนนขั้นต่ำที่กำหนด: TOEFL iBT ขั้นต่ำ 90 (แนะนำ 100), IELTS ขั้นต่ำ 7 (แนะนำ 7.5), Duolingo English Test ขั้นต่ำ 120','Early Action (EA): ยื่นภายใน 1 พฤศจิกายน ประกาศผลกลาง ธ.ค. | Regular Action (RA): ยื่นภายใน 4 มกราคม ประกาศผลกลาง มี.ค. (ต้องสอบ SAT/ACT ก่อน 30 พ.ย. สำหรับ EA และก่อน 31 ธ.ค. สำหรับ RA)','$75 USD (มีระบบขอยกเว้นค่าธรรมเนียมได้)','https://mitadmissions.org/apply/firstyear/deadlines-requirements/','2026-08-29',1,'2026-08-29 13:51:19'),
(62,'United States','สหรัฐอเมริกา','Stanford University','Stanford',2,'2','https://www.stanford.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application | ค่าธรรมเนียมสมัคร $100 (หรือขอยกเว้นได้) | คะแนน SAT หรือ ACT | แบบฟอร์มรายงานจากโรงเรียน (School Report) พร้อมจดหมายแนะนำจากอาจารย์แนะแนว | Transcript ทางการ/ผลการเรียน | Transcript ภาคเรียนกลางปี (midyear, ส่งภายใน 15 ก.พ.) | จดหมายแนะนำจากครูผู้สอน 2 ท่าน','ต้องส่งคะแนน ACT หรือ SAT แต่หน้าเว็บระบุว่าคะแนนเป็น optional สำหรับรุ่น Class of 2029 (มีความไม่สอดคล้องกันในหน้าเว็บเอง ควรตรวจสอบปีล่าสุด) ไม่มีคะแนนขั้นต่ำตายตัว พิจารณาตามบริบทผู้สมัคร ผู้เรียนหลักสูตร IB/A-Level ต้องส่งคะแนนคาดการณ์ (predicted grades) คะแนนภาษาอังกฤษ (English Proficiency Test) ไม่สามารถใช้แทนข้อกำหนด SAT/ACT ได้ ไม่พบคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Restrictive Early Action: ยื่นภายใน 1 พฤศจิกายน (หรือ 15 ต.ค. หากส่ง Arts Portfolio ด้วย) | Regular Decision: ยื่นภายใน 5 มกราคม (หรือ 5 ธ.ค. หากส่ง Arts Portfolio ด้วย)','$100 USD (มีระบบขอยกเว้นค่าธรรมเนียมได้)','https://admission.stanford.edu/apply/first-year/index.html','2026-08-29',2,'2026-08-29 13:51:19'),
(63,'United States','สหรัฐอเมริกา','Harvard University','Cambridge',5,'5','https://www.harvard.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application พร้อมคำถามเสริมของ Harvard (Short-answer 5 ข้อ จำกัด 150 คำ/ข้อ) | เรียงความส่วนตัว (Common App Essay) | ค่าธรรมเนียม $95 (หรือขอยกเว้นได้) | คะแนน SAT หรือ ACT (กรณีเข้าถึงข้อสอบไม่ได้ อาจใช้ AP/IB/GCSE-A-Level/National Leaving Exam แทนได้) | School Report พร้อมจดหมายแนะนำจากอาจารย์แนะแนว และ transcript | จดหมายแนะนำจากครูผู้สอน 2 ท่าน | Midyear School Report (หลังเกรดเทอมแรก)','รับคะแนน SAT หรือ ACT เป็นหลัก กรณีเข้าถึงข้อสอบไม่ได้ ยอมรับผลสอบทางเลือกอื่น (AP, IB, GCSE/A-Level, National Leaving Exam) แทนได้ ไม่พบระบุคะแนนขั้นต่ำตายตัว และไม่พบข้อกำหนดคะแนนภาษาอังกฤษ (TOEFL/IELTS) ขั้นต่ำในหน้าเว็บที่เข้าถึงได้ — Harvard ใช้เรียงความและการสัมภาษณ์เป็นหลักในการประเมินภาษาอังกฤษแทน','Restrictive Early Action (REA): ยื่นภายใน 1 พฤศจิกายน ประกาศผลกลาง ธ.ค. | Regular Decision (RD): ยื่นภายใน 1 มกราคม ประกาศผลปลาย มี.ค. (ระบบ Common App เปิดรับสมัคร 1 ส.ค.)','$95 USD (มีระบบขอยกเว้นค่าธรรมเนียมได้)','https://college.harvard.edu/admissions/apply/first-year-applicants','2026-08-29',3,'2026-08-29 13:51:19'),
(64,'United States','สหรัฐอเมริกา','California Institute of Technology (Caltech)','Pasadena',7,'7','https://www.caltech.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application หรือ QuestBridge Application | คะแนน SAT หรือ ACT (นับคะแนนย่อยแต่ละส่วนแยกกัน ไม่ใช้คะแนนรวม) | เรียงความเสริมของ Caltech | จดหมายแนะนำ | ค่าธรรมเนียมสมัคร (มีระบบขอยกเว้นได้)','บังคับส่งคะแนน SAT หรือ ACT (ไม่ใช่ test-optional) ใช้ระบบ \'bucket\' แบ่งช่วงคะแนนแทนคะแนนรวม: SAT 780-800 หรือ ACT 35-36 = Bucket A (ปกปิดคะแนนจริงจากกรรมการ), ต่ำกว่า 750 (Math SAT)/33 (ACT) = แสดงคะแนนจริงให้กรรมการเห็น ไม่พบคะแนนภาษาอังกฤษ (TOEFL/IELTS) ขั้นต่ำที่ระบุชัดในหน้าเว็บที่เข้าถึงได้','Restrictive Early Action (REA): ยื่นภายใน 1 พฤศจิกายน (ส่งเอกสารเพิ่มได้ถึง 6 พ.ย., สอบให้เสร็จก่อน 30 พ.ย.) ประกาศผลกลาง ธ.ค. | Regular Decision (RD): ยื่นภายใน 4 มกราคม (ส่งเอกสารเพิ่มได้ถึง 10 ม.ค., สอบให้เสร็จก่อน 31 ธ.ค.) ประกาศผลกลาง มี.ค.',NULL,'https://www.admissions.caltech.edu/apply/first-year-applicants/deadlines','2026-08-29',4,'2026-08-29 13:51:19'),
(65,'United States','สหรัฐอเมริกา','University of Pennsylvania','Philadelphia',15,'15','https://www.upenn.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common App, Coalition App หรือ QuestBridge | เรียงความ | Transcript ทางการ (ต้องแปลเป็นภาษาอังกฤษแบบรับรองถ้าไม่ใช่ภาษาอังกฤษ) | คะแนนสอบภาษาอังกฤษ (TOEFL/IELTS/Duolingo) หากไม่ได้เรียนเป็นภาษาอังกฤษมาอย่างน้อย 3 ปี','ไม่มีคะแนนขั้นต่ำตายตัวสำหรับผลการเรียน/ข้อสอบวิชาการ (Comprehensive Review พิจารณาบริบทผู้สมัครทั้งหมด) ยกเว้นภาษาอังกฤษที่ต้องการ: TOEFL iBT ระบบใหม่ (สเกล 1-6) ผู้สมัครที่แข่งขันได้มักมีคะแนนรวม 5 ขึ้นไป (ระบบเก่าสเกล 0-120 คะแนน 100 ขึ้นไป), IELTS ผู้สมัครที่แข่งขันได้มักมีคะแนนรวม 7 ขึ้นไป (เต็ม 9), Duolingo English Test ผู้สมัครที่แข่งขันได้มักมีคะแนน 130 ขึ้นไป (เต็ม 160) — ยกเว้นไม่ต้องสอบถ้าใช้ภาษาอังกฤษเป็นภาษาแม่ หรือเรียนเป็นภาษาอังกฤษมาอย่างน้อย 3 ปี ไม่รับ IELTS Indicator/One Skill Retake และไม่รับ MyBest score ของ TOEFL คะแนนใช้ได้ 2 ปีนับจากวันสอบ','Early Decision (ผูกมัด): ยื่นภายใน 1 พฤศจิกายน 2569 ประกาศผลเดือน ธ.ค. | Regular Decision: ยื่นภายใน 5 มกราคม 2570 ประกาศผลเดือน เม.ย.',NULL,'https://admissions.upenn.edu/how-to-apply/international-applicants','2026-08-29',5,'2026-08-29 13:51:19'),
(66,'United States','สหรัฐอเมริกา','Cornell University','Ithaca',16,'16','https://www.cornell.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','ใบสมัคร (Common App) | ค่าธรรมเนียมสมัครหรือขอยกเว้น | Transcript มัธยมปลายฉบับทางการ | School Report | จดหมายแนะนำจากอาจารย์แนะแนว | จดหมายแนะนำจากครูผู้สอน | Cornell University Supplement (เรียงความเสริมเฉพาะคอร์เนล) | คะแนนสอบมาตรฐาน (SAT หรือ ACT)','บังคับส่งคะแนน SAT หรือ ACT (ไม่ใช่ test-optional) ผู้สมัครต่างชาติต้องแสดงหลักฐานความสามารถภาษาอังกฤษด้วย อาจต้องส่งคะแนนสอบภาษาอังกฤษที่ได้รับการรับรอง — ไม่พบตัวเลขคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Early Decision (ผูกมัด): ยื่นใบสมัคร+ค่าธรรมเนียม ภายใน 1 พฤศจิกายน เอกสารอื่นภายใน 13 พ.ย. ประกาศผลกลาง ธ.ค. | Regular Decision: ยื่นใบสมัคร+ค่าธรรมเนียม ภายใน 2 มกราคม เอกสารอื่นภายใน 19 ม.ค. ประกาศผลปลาย มี.ค.',NULL,'https://admissions.cornell.edu/how-to-apply/first-year-applicants','2026-08-29',6,'2026-08-29 13:51:19'),
(67,'United States','สหรัฐอเมริกา','Yale University','New Haven',16,'16','https://www.yale.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common App, Coalition Application (SCOIR) หรือ QuestBridge (เลือกเพียง 1 ระบบ) | จดหมายแนะนำ | School Report พร้อม transcript | คะแนนสอบมาตรฐาน SAT หรือ ACT | เอกสารภาษาต่างประเทศต้องแนบคำแปลที่ได้รับการรับรอง (ห้ามแปลเอง) | คะแนนสอบภาษาอังกฤษ (TOEFL/IELTS/Cambridge/DET/InitialView) หากไม่ได้เรียนภาษาอังกฤษเป็นสื่อการสอนมาอย่างน้อย 2 ปี','บังคับส่งคะแนน SAT หรือ ACT ทั้งผู้สมัครในและต่างประเทศ (ไม่ใช่ test-optional และคะแนนสอบอื่น เช่น international leaving exam หรือคะแนนภาษาอังกฤษ ไม่สามารถใช้แทนได้) ไม่พบคะแนนขั้นต่ำตายตัวที่ระบุ (พิจารณาแบบ whole-person review) ไม่พบตัวเลขคะแนนภาษาอังกฤษขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Single-Choice Early Action: ยื่นภายใน 1 พฤศจิกายน | QuestBridge National College Match: ยื่นภายใน 1 พฤศจิกายน | Regular Decision: ยื่นภายใน 2 มกราคม',NULL,'https://admissions.yale.edu/apply','2026-08-29',7,'2026-08-29 13:51:19'),
(68,'United States','สหรัฐอเมริกา','Johns Hopkins University','Baltimore',20,'20','https://www.jhu.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application หรือ Coalition on Scoir | เรียงความเสริมของ Hopkins (Hopkins Supplement) | ค่าธรรมเนียมสมัคร $70 (หรือขอยกเว้นได้) | คะแนนสอบมาตรฐาน | สัญญา Early Decision ที่ลงนามแล้ว (เฉพาะผู้สมัครรอบ ED) | Secondary School Report จากโรงเรียน | จดหมายประเมินจากครู 2 ท่าน | รายงานผลการเรียนกลางปี (ส่งกลาง ก.พ.) | แบบฟอร์ม International Certification of Finances (เฉพาะนักเรียนต่างชาติ)','หน้าเว็บระบุว่าต้องส่ง \'คะแนนสอบมาตรฐาน\' เป็นส่วนหนึ่งของเอกสารที่ต้องยื่น แต่ไม่พบรายละเอียดว่าเป็น SAT/ACT บังคับหรือ test-optional และไม่พบคะแนนภาษาอังกฤษขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้ ควรตรวจสอบนโยบายล่าสุดจากหน้าเว็บโดยตรง','Early Decision I: ยื่นภายใน 1 พฤศจิกายน 2569 ประกาศผล 11 ธ.ค. 2569 | Early Decision II: ยื่นภายใน 2 มกราคม 2570 ประกาศผล 12 ก.พ. 2570 | Regular Decision: ยื่นภายใน 2 มกราคม 2570 ประกาศผล 24 มี.ค. 2570','$70 USD (หรือขอยกเว้นได้)','https://apply.jhu.edu/how-to-apply/application-deadlines-requirements/','2026-08-29',8,'2026-08-29 13:51:19'),
(69,'United States','สหรัฐอเมริกา','University of California, Berkeley (UCB)','Berkeley',20,'20','https://www.berkeley.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบ UC Application (ระบบกลางของ University of California ใช้ยื่นสมัครได้หลายแคมปัสพร้อมกัน) | ต้องเรียนครบวิชา A-G 15 วิชา (History 2 ปี, English 4 ปี, Math 3 ปี, Science 2 ปี, ภาษาอื่นนอกจากอังกฤษ 2 ปี, ศิลปะ 1 ปี, วิชาเลือกเสริม 1 ปี) เกรดต้องไม่ต่ำกว่า C | เรียงความตอบคำถาม Personal Insight Questions | ค่าธรรมเนียมสมัคร (แยกต่อแคมปัส)','ระบบ UC ไม่ใช้คะแนน SAT/ACT ในการพิจารณารับเข้าเรียนเลย (Test-blind ทั้งระบบ) กำหนด GPA ขั้นต่ำในวิชา A-G ที่ 3.0 (ผู้สมัครนอกรัฐแคลิฟอร์เนีย/ต่างชาติ ต้อง 3.4 ขึ้นไป) สำหรับภาษาอังกฤษ ต้องสอบผ่านเกณฑ์อย่างใดอย่างหนึ่งภายในเดือนธันวาคมของปีสุดท้ายมัธยม: IELTS 6.5 ขึ้นไป, TOEFL iBT ระบบใหม่ (ตั้งแต่ ม.ค. 2569) ขั้นต่ำ 4.5 หรือระบบเก่าขั้นต่ำ 80, Duolingo English Test ขั้นต่ำ 115, AP English คะแนน 3-5, IB English ระดับ SL คะแนน 6-7 หรือ HL คะแนน 5-7, ACT English 24 ขึ้นไป, SAT Writing and Language 31 ขึ้นไป (ไม่รับ IELTS One Skill Retake, MyBest TOEFL, หรือ digital SAT Reading&Writing section)','ยื่นใบสมัครผ่านระบบ UC Application ได้ตั้งแต่ 1 สิงหาคม ถึง 30 พฤศจิกายน (ภาคเรียนฤดูใบไม้ร่วง) ใช้ใบสมัครเดียวยื่นได้หลายแคมปัสในเครือ UC พร้อมกัน',NULL,'https://admission.universityofcalifornia.edu/admission-requirements/freshman-requirements/','2026-08-29',9,'2026-08-29 13:51:19'),
(70,'United States','สหรัฐอเมริกา','University of Chicago','Chicago',24,'24','https://www.uchicago.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application หรือ Coalition Application (Powered by Scoir) | เรียงความหลักและเรียงความเสริมของ UChicago | จดหมายประเมินจากครู 2 ท่าน | รายงานผลการเรียนกลางปี (Mid-Year Report) | ค่าธรรมเนียมสมัคร (หรือขอยกเว้นอัตโนมัติ) | Secondary School Report พร้อม transcript','ใช้นโยบาย \'No Harm Testing Policy\' คือคะแนน SAT/ACT เป็น optional จะไม่ส่งก็ได้โดยไม่เสียเปรียบ (ถ้าส่งจะถูกพิจารณาเป็นข้อมูลเสริมเท่านั้น) ไม่พบคะแนนขั้นต่ำหรือคะแนนภาษาอังกฤษ (TOEFL/IELTS) ที่ระบุชัดในหน้าที่เข้าถึงได้','Early Decision I: ยื่นภายใน 2 พฤศจิกายน 2569 ประกาศผลกลาง ธ.ค. | Early Action: ยื่นภายใน 2 พฤศจิกายน 2569 ประกาศผลกลาง ธ.ค. | Early Decision II: ยื่นภายใน 4 มกราคม 2570 ประกาศผลกลาง ก.พ. | Regular Decision: ยื่นภายใน 4 มกราคม 2570 ประกาศผลปลาย มี.ค.',NULL,'https://collegeadmissions.uchicago.edu/apply/application/','2026-08-29',10,'2026-08-29 13:51:19'),
(71,'United States','สหรัฐอเมริกา','Princeton University','Princeton',27,'27','https://www.princeton.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application (รหัส CEEB 2672) | คำถามเฉพาะของ Princeton | ค่าธรรมเนียมหรือขอยกเว้น | เรียงความวิชาการที่มีการให้เกรดแล้ว (Graded Written Paper) ในวิชาภาษาอังกฤษหรือประวัติศาสตร์ | Transcript ทางการ | School Report (SR) จากโรงเรียน | จดหมายแนะนำจากอาจารย์แนะแนว | จดหมายแนะนำจากครู 2 ท่าน (คนละสายวิชา) | รายงานผลการเรียนกลางปี','นโยบาย test-optional สำหรับผู้สมัครเข้าปีการศึกษา 2569 และ 2570 (จะกลับมาบังคับสอบอีกครั้งสำหรับผู้สมัครปีการศึกษา 2571) หากเลือกส่งคะแนนต้องสอบ SAT (รหัส 2672) หรือ ACT (รหัส 2588) ก่อนกำหนด ไม่รับ SAT Subject Tests คะแนนภาษาอังกฤษ (TOEFL/IELTS/DET/PTE Academic) บังคับเฉพาะผู้ที่ไม่ใช่เจ้าของภาษาและไม่ได้เรียนในโรงเรียนที่ใช้ภาษาอังกฤษเป็นสื่อการสอนอย่างน้อย 3 ปี ไม่พบคะแนนขั้นต่ำที่ระบุชัด','Single-Choice Early Action: ยื่นภายใน 1 พฤศจิกายน | Regular Decision: ยื่นภายใน 1 มกราคม',NULL,'https://admission.princeton.edu/apply/application-checklist','2026-08-29',11,'2026-08-29 13:51:19'),
(72,'United States','สหรัฐอเมริกา','Columbia University','New York City',43,'43','https://www.columbia.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application, Coalition Application (Scoir) หรือ QuestBridge | คำถามเฉพาะของ Columbia | Secondary School Report | จดหมายแนะนำจากครู | คะแนนสอบมาตรฐาน (ถ้าเลือกส่ง) | ค่าธรรมเนียมหรือขอยกเว้น | เอกสารเสริม (ไม่บังคับ)','Test-optional เต็มรูปแบบสำหรับรอบรับสมัคร 2026-2027 (จะเริ่มบังคับสอบอีกครั้งตั้งแต่ ส.ค. 2027 เป็นต้นไป) ไม่มีคะแนนขั้นต่ำที่กำหนดไว้เลย ไม่ได้เปรียบหรือเสียเปรียบจากการเลือกส่งหรือไม่ส่งคะแนน ไม่พบข้อกำหนดคะแนนภาษาอังกฤษ (TOEFL/IELTS) ที่ระบุชัดในหน้าที่เข้าถึงได้','Early Decision และ QuestBridge National College Match: ยื่นภายใน 1 พฤศจิกายน ประกาศผลกลาง ธ.ค. | Regular Decision: ยื่นภายใน 1 มกราคม ประกาศผลปลาย มี.ค.',NULL,'https://undergrad.admissions.columbia.edu/apply/first-year','2026-08-29',12,'2026-08-29 13:51:19'),
(73,'United States','สหรัฐอเมริกา','Northwestern University','Evanston',45,'45','https://www.northwestern.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application หรือ Coalition Application (Scoir) | เรียงความเสริมของ Northwestern | Transcript ทางการจากทุกโรงเรียนที่เคยเรียน พร้อม School Report จากโรงเรียนล่าสุด | จดหมายแนะนำจากอาจารย์แนะแนว | จดหมายแนะนำจากครูอย่างน้อย 1 ท่าน | สัญญา Early Decision (เฉพาะผู้สมัครรอบ ED) | หลักฐานความสามารถภาษาอังกฤษ (สำหรับผู้ที่ภาษาแรกไม่ใช่อังกฤษหรือไม่ได้เรียนเป็นภาษาอังกฤษมาก่อน) ยอมรับ Duolingo, IELTS (รวม IELTS Indicator), TOEFL iBT (รวม Special Home Edition แต่ไม่รับ TOEFL ITP Plus for China) | ค่าธรรมเนียมสมัคร $75 (หรือขอยกเว้นได้)','ไม่พบ SAT/ACT อยู่ในรายการเอกสารที่บังคับต้องส่ง (เข้าข่าย test-optional) ไม่พบคะแนนภาษาอังกฤษขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','QuestBridge: ยื่นภายใน 1 ตุลาคม 2569 | Early Decision: ยื่นภายใน 1 พฤศจิกายน 2569 ประกาศผล ธ.ค. 2569 | Regular Decision: ยื่นภายใน 4 มกราคม 2570 ประกาศผล มี.ค. 2570','$75 USD (หรือขอยกเว้นได้)','https://admissions.northwestern.edu/apply/index.html','2026-08-29',13,'2026-08-29 13:51:19'),
(74,'United States','สหรัฐอเมริกา','University of California, Los Angeles (UCLA)','Los Angeles',49,'49','https://www.ucla.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบ UC Application (ระบบกลางของ University of California ใช้ยื่นสมัครได้หลายแคมปัสพร้อมกัน) | ต้องเรียนครบวิชา A-G 15 วิชา (History 2 ปี, English 4 ปี, Math 3 ปี, Science 2 ปี, ภาษาอื่นนอกจากอังกฤษ 2 ปี, ศิลปะ 1 ปี, วิชาเลือกเสริม 1 ปี) เกรดต้องไม่ต่ำกว่า C | เรียงความตอบคำถาม Personal Insight Questions | ค่าธรรมเนียมสมัคร (แยกต่อแคมปัส)','ระบบ UC ไม่ใช้คะแนน SAT/ACT ในการพิจารณารับเข้าเรียนเลย (Test-blind ทั้งระบบ) กำหนด GPA ขั้นต่ำในวิชา A-G ที่ 3.0 (ผู้สมัครนอกรัฐแคลิฟอร์เนีย/ต่างชาติ ต้อง 3.4 ขึ้นไป) สำหรับภาษาอังกฤษ ต้องสอบผ่านเกณฑ์อย่างใดอย่างหนึ่งภายในเดือนธันวาคมของปีสุดท้ายมัธยม: IELTS 6.5 ขึ้นไป, TOEFL iBT ระบบใหม่ (ตั้งแต่ ม.ค. 2569) ขั้นต่ำ 4.5 หรือระบบเก่าขั้นต่ำ 80, Duolingo English Test ขั้นต่ำ 115, AP English คะแนน 3-5, IB English ระดับ SL คะแนน 6-7 หรือ HL คะแนน 5-7, ACT English 24 ขึ้นไป, SAT Writing and Language 31 ขึ้นไป (ไม่รับ IELTS One Skill Retake, MyBest TOEFL, หรือ digital SAT Reading&Writing section)','ยื่นใบสมัครผ่านระบบ UC Application ได้ตั้งแต่ 1 สิงหาคม ถึง 30 พฤศจิกายน (ภาคเรียนฤดูใบไม้ร่วง) ใช้ใบสมัครเดียวยื่นได้หลายแคมปัสในเครือ UC พร้อมกัน — ข้อกำหนดนี้เป็นข้อกำหนดร่วมของทุกแคมปัสในเครือ UC (Berkeley, UCLA, San Diego, Davis ฯลฯ)',NULL,'https://admission.universityofcalifornia.edu/admission-requirements/freshman-requirements/','2026-08-29',14,'2026-08-29 13:51:19'),
(75,'United States','สหรัฐอเมริกา','University of Michigan-Ann Arbor','Ann Arbor',51,'51','https://umich.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application พร้อมค่าธรรมเนียม $75 | Transcript มัธยมปลาย (มีข้อกำหนดเพิ่มเติมตามประเทศ) | School Report (Common App) | จดหมายประเมินจากครู 1 ท่าน | คะแนน SAT หรือ ACT (ถ้ามีและต้องการให้พิจารณา ไม่บังคับ) | คะแนน TOEFL/IELTS/MET ฯลฯ (สำหรับผู้ที่ไม่ใช่เจ้าของภาษาอังกฤษ) | Transcript วิทยาลัยทางการ (ถ้าเรียน dual-enrollment) | สัญญา Early Decision ที่ลงนามแล้ว (เฉพาะรอบ ED)','Test-optional คะแนน SAT/ACT ส่งได้ถ้ามีและต้องการให้พิจารณา ไม่บังคับ รับคะแนนแบบ self-report ได้โดยไม่ต้องรอสถาบันสอบส่งตรง ไม่พบคะแนนภาษาอังกฤษขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Early Decision/Early Action: ยื่นภายใน 1 พฤศจิกายน ประกาศผล ED ภายในสิ้น ธ.ค., ประกาศผล EA ภายในสิ้น ม.ค. | Regular Decision: ยื่นภายใน 1 กุมภาพันธ์ ประกาศผลต้นเดือน เม.ย.','$75 USD (นักเรียนต่างชาติมักไม่เข้าเงื่อนไขขอยกเว้นค่าธรรมเนียม)','https://admissions.umich.edu/apply/first-year-applicants/requirements-deadlines','2026-08-29',15,'2026-08-29 13:51:19'),
(76,'United States','สหรัฐอเมริกา','Carnegie Mellon University','Pittsburgh',55,'55','https://www.cmu.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application พร้อมค่าธรรมเนียม $75 (หรือขอยกเว้นได้) | คะแนนสอบมาตรฐาน (TOEFL/IELTS/Duolingo หากภาษาอังกฤษไม่ใช่ภาษาแม่) | จดหมายประเมินจากอาจารย์แนะแนว | จดหมายแนะนำจากครู | เรียงความ Common Application Essay | เรียงความเสริมของ Carnegie Mellon (คำถามสั้น 3 ข้อ) — ไม่รับเอกสารเสริมอื่น เช่น resume/ผลงาน/วิดีโอ ยกเว้นคณะ Fine Arts ที่ต้องส่ง portfolio/ออดิชันแยกต่างหาก','หน้าเว็บระบุ \'Standardized Testing Scores\' เป็นเอกสารที่ต้องส่ง แต่ระบุชัดเฉพาะกรณีภาษาอังกฤษไม่ใช่ภาษาแม่ (ต้องส่ง TOEFL/IELTS/Duolingo) ไม่ได้ระบุชัดว่า SAT/ACT บังคับหรือไม่สำหรับผู้สมัครทั่วไป ไม่พบคะแนนขั้นต่ำที่ระบุ ควรตรวจสอบหน้าเว็บล่าสุดโดยตรง','Early Decision (ผูกมัด): ยื่นภายใน 2 พฤศจิกายน ประกาศผลกลาง ธ.ค. (15 ธ.ค.) | Regular Decision: ยื่นภายใน 4 มกราคม ประกาศผลภายใน 1 เม.ย. (คณะ Drama/Music: ยื่นภายใน 1 ธ.ค.)','$75 USD (หรือขอยกเว้นได้)','https://www.cmu.edu/admission/admission/undergraduate-admission-requirements','2026-08-29',16,'2026-08-29 13:51:19'),
(77,'United States','สหรัฐอเมริกา','New York University (NYU)','New York City',58,'58','https://www.nyu.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application | Transcript/เอกสารการศึกษา (รับได้ทั้งฉบับทางการและไม่เป็นทางการเพื่อพิจารณาใบสมัคร) | คำแปลภาษาอังกฤษที่รับรองแล้วถ้าเอกสารไม่ใช่ภาษาอังกฤษ (ยกเว้นภาษาจีนกลางสำหรับ NYU Shanghai) | หลักฐานความสามารถภาษาอังกฤษ (สำหรับผู้สมัครต่างชาติ) | Portfolio/ออดิชัน (เฉพาะโปรแกรมที่กำหนด) | ค่าธรรมเนียมหรือขอยกเว้น','Test-optional ต่อเนื่องถึงรอบรับสมัคร 2027-2028 เลือกส่งได้ 1 ประเภทจาก SAT, ACT, AP, IB Diploma, GCE A-Level หรือข้อสอบนานาชาติอื่นๆ (เลือกได้แค่ 1 แบบ) รับคะแนนแบบ self-report ผ่าน portal ได้ก่อน ถ้าตอบรับเข้าเรียนต้องส่งคะแนนทางการภายหลัง ไม่พบคะแนนขั้นต่ำที่ระบุชัด','Early Decision I: ยื่นภายใน 1 พฤศจิกายน ประกาศผล 15 ธ.ค. | Early Decision II: ยื่นภายใน 1 มกราคม ประกาศผล 15 ก.พ. | Regular Decision: ยื่นภายใน 5 มกราคม ประกาศผล 1 เม.ย.',NULL,'https://www.nyu.edu/admissions/undergraduate-admissions/how-to-apply/all-freshmen-applicants.html','2026-08-29',17,'2026-08-29 13:51:19'),
(78,'United States','สหรัฐอเมริกา','Brown University','Providence',66,'66','https://www.brown.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application พร้อม Brown Member section | เรียงความเสริมของ Brown (ผ่าน Common App) | ค่าธรรมเนียม $80 (หรือขอยกเว้นได้) | Transcript ทางการ | School Report จากโรงเรียน | จดหมายแนะนำจากอาจารย์แนะแนว | จดหมายแนะนำจากครู 2 ท่าน (คนละสายวิชาหลัก) | สัญญา Early Decision (เฉพาะรอบ ED) | รายงานผลการเรียนไตรมาสแรก (เฉพาะ ED) และรายงานผลการเรียนกลางปี (ทุกคน) | เรียงความพิเศษเพิ่มเติมถ้าสมัคร PLME หรือ Brown|RISD Dual Degree','กลับมาบังคับส่งคะแนน SAT หรือ ACT ตั้งแต่รอบรับสมัคร 2024-25 เป็นต้นไป (ไม่ใช่ test-optional แล้ว) ใช้ระบบ superscore ทั้ง SAT และ ACT ส่วน SAT Essay/ACT Writing ยังคงเป็นทางเลือก ไม่มีคะแนนขั้นต่ำตายตัว พิจารณาตามบริบทผู้สมัคร','Early Decision (ผูกมัด): ยื่นภายใน 1 พฤศจิกายน | Regular Decision: ยื่นภายใน 5 มกราคม ประกาศผลต้นเดือน เม.ย.','$80 USD (หรือขอยกเว้นได้)','https://admission.brown.edu/first-year/application-checklist','2026-08-29',18,'2026-08-29 13:51:19'),
(79,'United States','สหรัฐอเมริกา','Duke University','Durham',70,'70','https://www.duke.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application หรือ QuestBridge Application | Transcript ทางการ | คะแนนสอบมาตรฐาน (ถ้าเลือกส่ง) | จดหมายแนะนำ | กิจกรรมนอกหลักสูตร | เรียงความ | ค่าธรรมเนียมหรือขอยกเว้น','Test-optional สำหรับรอบรับสมัคร 2026-2027 มีข้อกำหนดคะแนนภาษาอังกฤษ (English Proficiency Tests) แยกต่างหากสำหรับผู้สมัครต่างชาติ แต่ไม่พบตัวเลขคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้ ควรตรวจสอบหน้าเว็บโดยตรง','Early Decision: ยื่นภายใน 2 พฤศจิกายน | Regular Decision: ยื่นภายใน 4 มกราคม (ข้อมูลสำหรับรอบรับสมัคร 2026-27)',NULL,'https://admissions.duke.edu/apply','2026-08-29',19,'2026-08-29 13:51:19'),
(80,'United States','สหรัฐอเมริกา','University of Texas at Austin','Austin',72,'72','https://www.utexas.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common App หรือ ApplyTexas | ค่าธรรมเนียม $90 สำหรับนักเรียนต่างชาติ (ไม่มีระบบขอยกเว้นสำหรับนักเรียนต่างชาติ) | เรียงความและคำถามสั้นอย่างน้อย 1 ข้อ | คะแนน SAT (รหัส 6882) หรือ ACT (รหัส 4240) อย่างน้อย 1 วิชา ส่งตรงจากสถาบันสอบ | Transcript มัธยมปลายที่แสดงว่าจบหรือกำลังจะจบเทียบเท่าเกรด 9-12 ของสหรัฐฯ | TOEFL/IELTS/DET (ตามที่สาขาวิชากำหนด)','บังคับส่งคะแนน SAT หรือ ACT อย่างน้อย 1 รายการ (ไม่ใช่ test-optional) ไม่รับ SAT Essay, ACT Writing, ACT Science section หรือ SAT Subject Tests คะแนนภาษาอังกฤษ TOEFL/IELTS/DET ระบุเป็น \'รายการเฉพาะสาขา\' อาจจำเป็นสำหรับบางสาขาเท่านั้น ไม่พบคะแนนขั้นต่ำที่ระบุชัด','Early Action: ยื่นภายใน 15 ตุลาคม (เอกสารเสริมภายใน 22 ต.ค.) ประกาศผล 15 ม.ค. | Regular Decision: ยื่นภายใน 1 ธันวาคม (เอกสารเสริมภายใน 10 ธ.ค.) ประกาศผล 15 ก.พ.','$90 USD สำหรับนักเรียนต่างชาติ (ไม่มีระบบขอยกเว้น)','https://admissions.utexas.edu/apply/international/','2026-08-29',20,'2026-08-29 13:51:19'),
(81,'United States','สหรัฐอเมริกา','University of Illinois Urbana-Champaign','Champaign',74,'74','https://illinois.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบสมัครของ University of Illinois | ค่าธรรมเนียมหรือขอยกเว้น | Self-Reported Academic Record (SRAR) แทน transcript ทางการช่วงสมัคร | คะแนนสอบมาตรฐาน (เลือกส่งได้ ไม่บังคับ) | คะแนนภาษาอังกฤษ (ถ้ากำหนด สำหรับผู้สมัครต่างชาติ) | ต้องเรียนวิชาพื้นฐานครบตามที่กำหนด (ภาษาอังกฤษ, คณิตศาสตร์, สังคมศาสตร์, วิทยาศาสตร์เชิงปฏิบัติการ, ภาษาอื่นนอกจากอังกฤษ)','Test-optional คะแนนสอบมาตรฐานเป็น \'รายการที่เลือกส่งได้ตามต้องการ\' ไม่บังคับ ไม่พบคะแนนขั้นต่ำที่ระบุชัด คะแนนภาษาอังกฤษ (English Language Proficiency) บังคับเฉพาะกรณีที่มหาวิทยาลัยกำหนดสำหรับผู้สมัครต่างชาติ ไม่พบตัวเลขคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Early Action: ยื่นภายใน 1 พฤศจิกายน (เอกสารเสริมภายใน 7 พ.ย.) ประกาศผล 29 ม.ค. | Regular Decision: ยื่นภายใน 5 มกราคม (เอกสารเสริมภายใน 11 ม.ค.) ประกาศผล 26 ก.พ.',NULL,'https://admissions.illinois.edu/Apply/Freshman/requirements','2026-08-29',21,'2026-08-29 13:51:19'),
(82,'United States','สหรัฐอเมริกา','University of California, San Diego (UCSD)','San Diego',81,'81','https://www.ucsd.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบ UC Application (ระบบกลางของ University of California ใช้ยื่นสมัครได้หลายแคมปัสพร้อมกัน) | ต้องเรียนครบวิชา A-G 15 วิชา (History 2 ปี, English 4 ปี, Math 3 ปี, Science 2 ปี, ภาษาอื่นนอกจากอังกฤษ 2 ปี, ศิลปะ 1 ปี, วิชาเลือกเสริม 1 ปี) เกรดต้องไม่ต่ำกว่า C | เรียงความตอบคำถาม Personal Insight Questions | ค่าธรรมเนียมสมัคร (แยกต่อแคมปัส)','ระบบ UC ไม่ใช้คะแนน SAT/ACT ในการพิจารณารับเข้าเรียนเลย (Test-blind ทั้งระบบ) กำหนด GPA ขั้นต่ำในวิชา A-G ที่ 3.0 (ผู้สมัครนอกรัฐแคลิฟอร์เนีย/ต่างชาติ ต้อง 3.4 ขึ้นไป) สำหรับภาษาอังกฤษ ต้องสอบผ่านเกณฑ์อย่างใดอย่างหนึ่งภายในเดือนธันวาคมของปีสุดท้ายมัธยม: IELTS 6.5 ขึ้นไป, TOEFL iBT ระบบใหม่ (ตั้งแต่ ม.ค. 2569) ขั้นต่ำ 4.5 หรือระบบเก่าขั้นต่ำ 80, Duolingo English Test ขั้นต่ำ 115, AP English คะแนน 3-5, IB English ระดับ SL คะแนน 6-7 หรือ HL คะแนน 5-7, ACT English 24 ขึ้นไป, SAT Writing and Language 31 ขึ้นไป (ไม่รับ IELTS One Skill Retake, MyBest TOEFL, หรือ digital SAT Reading&Writing section)','ยื่นใบสมัครผ่านระบบ UC Application ได้ตั้งแต่ 1 สิงหาคม ถึง 30 พฤศจิกายน (ภาคเรียนฤดูใบไม้ร่วง) ใช้ใบสมัครเดียวยื่นได้หลายแคมปัสในเครือ UC พร้อมกัน — ข้อกำหนดนี้เป็นข้อกำหนดร่วมของทุกแคมปัสในเครือ UC (Berkeley, UCLA, San Diego, Davis ฯลฯ)',NULL,'https://admission.universityofcalifornia.edu/admission-requirements/freshman-requirements/','2026-08-29',22,'2026-08-29 13:51:19'),
(83,'United States','สหรัฐอเมริกา','Pennsylvania State University','University Park',92,'92','https://www.psu.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบ MyPennState หรือ Common App | Transcript มัธยมปลาย ต้องเรียนวิชาพื้นฐานครบ (ภาษาอังกฤษ 4 หน่วยกิต, สังคม/ศิลปะ/มนุษยศาสตร์ 3 หน่วยกิต, วิทยาศาสตร์ 3 หน่วยกิต, คณิตศาสตร์ 3 หน่วยกิต, ภาษาอื่นนอกจากอังกฤษ 2 หน่วยกิต) | ค่าธรรมเนียมหรือขอยกเว้น | คะแนนสอบ (self-report ได้ ถ้าเลือกส่ง)','มีนโยบาย test-optional รับคะแนนแบบ self-report ได้ ไม่บังคับส่วนเสริม Enhanced ACT Science section ไม่พบคะแนนขั้นต่ำหรือคะแนนภาษาอังกฤษที่ระบุชัดในหน้าที่เข้าถึงได้','Early Action: ยื่นภายใน 1 พฤศจิกายน ประกาศผลภายใน 24 ธ.ค. | กำหนดส่งใบสมัครที่แนะนำสำหรับทุกคน: 1 ธันวาคม (ระบบรับสมัครแบบทยอยพิจารณา ไม่ใช่ระบบ ED/RD แบบตายตัว)',NULL,'https://www.psu.edu/admission/undergraduate/how-to-apply','2026-08-29',23,'2026-08-29 13:51:19'),
(84,'United States','สหรัฐอเมริกา','University of Washington','Seattle',92,'92','https://www.washington.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบสมัครของ UW (Coalition Application) | เรียงความ | Transcript | คะแนนสอบมาตรฐาน (ถ้าเลือกส่ง กำหนดส่งภายใน 31 ธ.ค.) | หลักฐานความสามารถภาษาอังกฤษ (เฉพาะนักเรียนต่างชาติ)','ใช้ระบบพิจารณาแบบองค์รวม (Holistic Review) ไม่พบระบุคะแนนขั้นต่ำตายตัว มีกำหนดส่งคะแนนสอบภายใน 31 ธันวาคม สำหรับผู้ที่เลือกส่ง ไม่พบคะแนนภาษาอังกฤษขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','ใช้ระบบยื่นครั้งเดียว (ไม่มีรอบ ED/EA/RD แยก): ยื่นภายใน 15 พฤศจิกายน (เปิดรับสมัคร 15 ส.ค.) คะแนนสอบส่งได้ถึง 31 ธ.ค. ประกาศผลช่วง 1-15 มี.ค.',NULL,'https://admit.washington.edu/apply/dates/','2026-08-29',24,'2026-08-29 13:51:19'),
(85,'United States','สหรัฐอเมริกา','Boston University','Boston',94,'94','https://www.bu.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application หรือ QuestBridge Application | High School Transcript | เกรดปีสุดท้าย | School Report + จดหมายแนะนำจากอาจารย์แนะแนว | จดหมายประเมินจากครู | คะแนนสอบมาตรฐาน (ไม่บังคับ) | เรียงความ 2 ฉบับ (Common App Personal Statement + BU Supplemental Essay) | ค่าธรรมเนียม $80 (หรือขอยกเว้นได้) | Video Submission (ไม่บังคับ) | ข้อกำหนดเพิ่มเติมสำหรับ College of Fine Arts (portfolio/ออดิชัน)','Test-optional คะแนนสอบมาตรฐานระบุชัดว่าเป็น \'Optional\' ไม่บังคับ ไม่พบคะแนนขั้นต่ำหรือคะแนนภาษาอังกฤษที่ระบุชัดในหน้าที่เข้าถึงได้','Early Decision I (ผูกมัด): ยื่นภายใน 2 พฤศจิกายน ประกาศผล 15 ธ.ค. | Early Decision II: ยื่นภายใน 5 มกราคม ประกาศผล 9 ก.พ. | Regular Decision: ยื่นภายใน 5 มกราคม ประกาศผล 28 มี.ค.','$80 USD (หรือขอยกเว้นได้)','https://www.bu.edu/admissions/apply/first-year/','2026-08-29',25,'2026-08-29 13:51:19'),
(86,'United States','สหรัฐอเมริกา','Purdue University','West Lafayette',100,'100','https://www.purdue.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common App | ต้องระบุสาขาวิชาที่สมัครตั้งแต่ตอนยื่นใบสมัคร | Transcript อย่างน้อย 3 ปีติดต่อกัน พร้อมหลักฐานจบมัธยมปลาย/ประกาศนียบัตร | คำแปลภาษาอังกฤษที่รับรองแล้ว (ถ้าเอกสารไม่ใช่ภาษาอังกฤษ) | เอกสารเพิ่มเติมตามประเทศต้นทาง | หลักฐานความสามารถภาษาอังกฤษ (สำหรับนักเรียนต่างชาติ ยกเว้นข้อกำหนดภาษาต่างประเทศถ้ามาจากประเทศที่ไม่ใช้ภาษาอังกฤษ)','ไม่พบระบุชัดว่า SAT/ACT บังคับหรือไม่สำหรับผู้สมัครทั่วไปในหน้าที่เข้าถึงได้ มีข้อกำหนดคะแนนภาษาอังกฤษขั้นต่ำสำหรับนักเรียนต่างชาติ แต่ไม่พบตัวเลขที่ระบุชัดในหน้านี้ ควรตรวจสอบหน้า English Proficiency Requirements โดยตรง','ใช้ระบบยื่นครั้งเดียวไม่มีรอบ ED/EA/RD แยก: เปิดรับสมัครภาคเรียนฤดูใบไม้ร่วง (Fall) ตั้งแต่ 1 สิงหาคม ถึง 15 มกราคม',NULL,'https://admissions.purdue.edu/become-student/apply/','2026-08-29',26,'2026-08-29 13:51:19'),
(87,'United States','สหรัฐอเมริกา','Rice University','Houston',122,'122','https://www.rice.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','Common Application พร้อมเรียงความเสริมของ Rice | ค่าธรรมเนียม $75 (ชำระออนไลน์เท่านั้น) | Transcript มัธยมปลายทางการ | จดหมายแนะนำจากอาจารย์แนะแนว + ครู 2 ท่าน | Portfolio สถาปัตยกรรม (เฉพาะผู้สมัครคณะสถาปัตยกรรม) | คะแนน SAT หรือ ACT (มีกำหนดวันสอบล่าสุดที่ใช้ได้ระบุไว้ในตารางกำหนดการ)','หน้าตารางกำหนดการระบุ \'Last applicable SAT/ACT\' เป็นส่วนหนึ่งของกำหนดการ Regular Decision บ่งชี้ว่าคะแนนสอบเป็นส่วนหนึ่งของการพิจารณา แต่ไม่พบระบุชัดเจนว่าบังคับหรือ test-optional ไม่พบคะแนนขั้นต่ำที่ระบุชัด ควรตรวจสอบหน้า Standardized Testing โดยตรง','Regular Decision: ยื่นภายใน 4 มกราคม (คะแนนสอบ SAT/ACT ล่าสุดที่ใช้ได้คือรอบสอบเดือนธันวาคม)','$75 USD (ชำระออนไลน์เท่านั้น)','https://admission.rice.edu/apply/first-year-applicants','2026-08-29',27,'2026-08-29 13:51:19'),
(88,'United States','สหรัฐอเมริกา','University of Wisconsin-Madison','Madison',131,'131','https://www.wisc.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application หรือ Universities of Wisconsin Application (เลือกได้ทั้งคู่ ไม่มีข้อได้เปรียบต่างกัน) | ค่าธรรมเนียมสมัคร | เรียงความ 2 ฉบับ | ข้อมูลรายวิชาและเกรด | จดหมายแนะนำอย่างน้อย 1 ฉบับ | คะแนน TOEFL, IELTS หรือ DET (บังคับสำหรับผู้ที่ต้องแสดงความสามารถภาษาอังกฤษ)','Test-optional ต่อเนื่องถึงภาคเรียนฤดูใบไม้ผลิ 2028 (สปริง 2571) คะแนน SAT/ACT เป็นรายการเสริมไม่บังคับ ส่วนคะแนนภาษาอังกฤษ TOEFL/IELTS/DET เป็นรายการบังคับ (ข้อ 6 ในรายการเอกสารที่ต้องส่ง) แต่ไม่พบตัวเลขคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Fall Early Action: ยื่นภายใน 1 พฤศจิกายน (เอกสารภายใน 9 พ.ย.) ประกาศผลภายใน 31 ม.ค. | Fall Regular Decision: ยื่นภายใน 15 มกราคม (เอกสารภายใน 22 ม.ค.) ประกาศผลภายใน 31 มี.ค.',NULL,'https://admissions.wisc.edu/apply-as-a-freshman/','2026-08-29',28,'2026-08-29 13:51:19'),
(89,'United States','สหรัฐอเมริกา','University of California, Davis','Davis',137,'137','https://www.ucdavis.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่านระบบ UC Application (ระบบกลางของ University of California ใช้ยื่นสมัครได้หลายแคมปัสพร้อมกัน) | ต้องเรียนครบวิชา A-G 15 วิชา (History 2 ปี, English 4 ปี, Math 3 ปี, Science 2 ปี, ภาษาอื่นนอกจากอังกฤษ 2 ปี, ศิลปะ 1 ปี, วิชาเลือกเสริม 1 ปี) เกรดต้องไม่ต่ำกว่า C | เรียงความตอบคำถาม Personal Insight Questions | ค่าธรรมเนียมสมัคร (แยกต่อแคมปัส)','ระบบ UC ไม่ใช้คะแนน SAT/ACT ในการพิจารณารับเข้าเรียนเลย (Test-blind ทั้งระบบ) กำหนด GPA ขั้นต่ำในวิชา A-G ที่ 3.0 (ผู้สมัครนอกรัฐแคลิฟอร์เนีย/ต่างชาติ ต้อง 3.4 ขึ้นไป) สำหรับภาษาอังกฤษ ต้องสอบผ่านเกณฑ์อย่างใดอย่างหนึ่งภายในเดือนธันวาคมของปีสุดท้ายมัธยม: IELTS 6.5 ขึ้นไป, TOEFL iBT ระบบใหม่ (ตั้งแต่ ม.ค. 2569) ขั้นต่ำ 4.5 หรือระบบเก่าขั้นต่ำ 80, Duolingo English Test ขั้นต่ำ 115, AP English คะแนน 3-5, IB English ระดับ SL คะแนน 6-7 หรือ HL คะแนน 5-7, ACT English 24 ขึ้นไป, SAT Writing and Language 31 ขึ้นไป (ไม่รับ IELTS One Skill Retake, MyBest TOEFL, หรือ digital SAT Reading&Writing section)','ยื่นใบสมัครผ่านระบบ UC Application ได้ตั้งแต่ 1 สิงหาคม ถึง 30 พฤศจิกายน (ภาคเรียนฤดูใบไม้ร่วง) ใช้ใบสมัครเดียวยื่นได้หลายแคมปัสในเครือ UC พร้อมกัน — ข้อกำหนดนี้เป็นข้อกำหนดร่วมของทุกแคมปัสในเครือ UC (Berkeley, UCLA, San Diego, Davis ฯลฯ)',NULL,'https://admission.universityofcalifornia.edu/admission-requirements/freshman-requirements/','2026-08-29',29,'2026-08-29 13:51:19'),
(90,'United States','สหรัฐอเมริกา','Georgia Institute of Technology','Atlanta',142,'142','https://www.gatech.edu','โดยทั่วไปสมัครผ่านระบบ Common Application หรือเว็บสมัครของมหาวิทยาลัยเอง ใช้ผลการเรียน (GPA/Transcript), เรียงความส่วนตัว (Personal Essay), จดหมายแนะนำจากครู, กิจกรรมนอกหลักสูตร และคะแนนภาษาอังกฤษ (TOEFL/IELTS) สำหรับนักเรียนต่างชาติ หลายแห่งเป็น test-optional ไม่บังคับ SAT/ACT แล้ว ปฏิทินหลักคือรอบ Early Decision/Early Action (ยื่นประมาณเดือน พ.ย.) และ Regular Decision (ยื่นประมาณเดือน ม.ค.) แต่ละมหาวิทยาลัยกำหนดวันที่และเกณฑ์เฉพาะของตัวเอง ควรตรวจสอบจากเว็บไซต์แอดมิชชันของมหาวิทยาลัยนั้นโดยตรง','สมัครผ่าน Common Application เท่านั้น | Transcript แสดงรายวิชาเกรด 9-12 (เกรด 9-11 ต้องเห็นผลการเรียนแล้ว, ผู้สมัครรอบ RD/ถูกเลื่อนพิจารณาต้องส่ง transcript เทอมล่าสุดเพิ่ม) | คะแนน SAT/ACT (self-report หรือทางการ) | เอกสารเพิ่มเติมตามที่ระบุใน portal | หลักฐานความสามารถภาษาอังกฤษตามเกณฑ์ University System of Georgia (USG) สำหรับนักเรียนต่างชาติ | ค่าธรรมเนียม $75 (นักเรียนต่างชาติ $85)','คะแนน SAT/ACT (self-reported หรือทางการ) เป็นส่วนหนึ่งของ \'ใบสมัครที่สมบูรณ์\' ที่ระบุไว้ชัดเจน (ไม่ใช่ test-optional เต็มรูปแบบ) นักเรียนต่างชาติต้องผ่านเกณฑ์ภาษาอังกฤษตามวิธีที่ USG รับรอง (มีวิธีหลากหลาย) เสริมด้วย Duolingo/InitialView/Vericant ได้แต่ไม่ใช้แทนข้อกำหนดหลัก ไม่พบคะแนนขั้นต่ำที่ระบุชัดในหน้าที่เข้าถึงได้','Early Action 1: ยื่นภายใน 15 ตุลาคม (เอกสารภายใน 30 ต.ค., คะแนนสอบภายใน 16 พ.ย.) ประกาศผลต้น ธ.ค. | Early Action 2: ยื่นภายใน 2 พฤศจิกายน (เอกสารภายใน 16 พ.ย., คะแนนสอบภายใน 8 ธ.ค.) ประกาศผลปลาย ม.ค. | Regular Decision: ยื่นภายใน 6 มกราคม (เอกสารและคะแนนสอบภายใน 22 ม.ค.) ประกาศผลกลาง มี.ค.','$75 USD (นักเรียนต่างชาติ $85 USD)','https://admission.gatech.edu/first-year/deadlines','2026-08-29',30,'2026-08-29 13:51:19'),
(91,'China','จีน','Peking University','Beijing',13,'13','https://english.pku.edu.cn','นักเรียนต่างชาติส่วนใหญ่สมัครผ่านระบบรับนักศึกษาต่างชาติ (International Students Admission) ของแต่ละมหาวิทยาลัยโดยตรง ไม่ใช่ระบบเกาเข่า (Gaokao) ที่ใช้กับนักเรียนจีน ใช้ Transcript, แผนการศึกษา/หนังสือแสดงเจตจำนง (Study Plan / Statement of Purpose), จดหมายแนะนำ และคะแนนภาษาอังกฤษ (IELTS/TOEFL) หรือคะแนนภาษาจีน HSK สำหรับหลักสูตรที่สอนเป็นภาษาจีน กำหนดการและเกณฑ์ต่างกันมากในแต่ละมหาวิทยาลัย ควรตรวจสอบจากเว็บไซต์แอดมิชชันนานาชาติของมหาวิทยาลัยนั้นโดยตรง',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-08-29 13:51:19'),
